"""Core CS MCQ bank II: 150 new questions, none repeated from bank I. Same format as mcq_data.py:
(question, correct, wrong1, wrong2, wrong3, explanation[, code]). test_mcq2.py checks every computable answer."""
SECTIONS = []
def sec(key, title, kb, qs): SECTIONS.append(dict(key=key, title=title, kb=kb, qs=qs))
INC = "#include <bits/stdc++.h>\nusing namespace std;\n"
def C(code, out, w1, w2, w3, why): return ("What does this print?", out, w1, w2, w3, why, INC + code)

